/* 编号只是原值；n 为正，右移次数可很大但每 n 次回到原表。 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int main(void)  {
    int n;
    long long k, values[10000];
    scanf("%d%lld", &n, &k);
    for (int i = 0; i < n; ++i)  {
        scanf("%lld", &values[i]);
    }
    int
    /* shift=k%n；结果位置 i 的来源是 (i-shift+n)%n，等价于尾段接到开头。 */
    shift = (int)(k % n);
    for (int i = 0; i < n; ++i)  {
        if (i > 0)  {
            /* 按结果位置输出全部 n 项，Python 切片拼接会另外建立结果列表。 */
            printf(" ");
        }
        printf("%lld", values[(i - shift + n) % n]);
    }
    printf("\n");
    return 0;
}

